const ELE_PAL=[268,205,150,25,340,48,175,5]; // ชุดสีเดียวกับนกฮูก → seed เดียวกันได้โทนเดียวกัน
const ELE_CACHE={};
function eleHue(seed){let a=((seed||1)*3+5)>>>0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;const r=((t^t>>>14)>>>0)/4294967296;return ELE_PAL[Math.floor(r*ELE_PAL.length)];}
// ร่าง 2-3 ใส่สีตาม seed (ใบหูคงชมพูเดิม) · ร่าง 4 ใช้สีตามดีไซน์ที่ออกแบบไว้
function elephantSrc(key,seed){
  const h=eleHue(seed),tint=key==='s2'||key.startsWith('s3_'),ck=key+'|'+(tint?h:'fixed');
  if(ELE_CACHE[ck])return ELE_CACHE[ck];
  let s=ELEPHANT_ART[key];
  if(tint)s=s.replace(/:root\{--body:[^;]+;--belly:[^;]+;(--ear:[^;]+;)--line:[^}]+\}/,`:root{--body:hsl(${h},38%,74%);--belly:hsl(${h},60%,94%);$1--line:hsl(${h},26%,58%)}`);
  return ELE_CACHE[ck]='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(s);
}
window.ART=window.ART||{};
ART.elephant={data:ELEPHANT_ART,src:elephantSrc};
